const languageKey = 'course-classrooms.language';
let language = 'zh-CN';
try {
  if (globalThis.localStorage?.getItem(languageKey) === 'en') language = 'en';
} catch {}

export function getLanguage() {
  return language;
}

export function setLanguage(next) {
  if (next !== 'zh-CN' && next !== 'en') return;
  language = next;
  try {
    globalThis.localStorage?.setItem(languageKey, next);
  } catch {}
}

const punctuation = {'。': '.', '，': ', ', '：': ': ', '？': '?', '！': '!'};
const staticMessages = Object.keys(english)
  .sort((left, right) => right.length - left.length)
  .map(message => message.replace(/[.*+?^$${}()|[\]\\]/g, '\\$&'));
const pattern = new RegExp(staticMessages.concat(Object.keys(punctuation)).join('|'), 'gu');
const translatedTemplates = new WeakMap();

function translateStatic(text) {
  return text.replace(pattern, match => english[match] ?? punctuation[match]);
}

// Localize interface text only. Interpolated values may be names, comments, or code.
export function ui(message, ...values) {
  if (typeof message === 'string') {
    return language === 'en' ? translateStatic(message) : message;
  }
  let fragments = message;
  if (language === 'en') {
    fragments = translatedTemplates.get(message);
    if (!fragments) {
      fragments = message.map(translateStatic);
      translatedTemplates.set(message, fragments);
    }
  }
  return fragments.reduce((text, fragment, index) => text + fragment + (index < values.length ? String(values[index]) : ''), '');
}
